/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-10","number":10,"title":"The Advanced Arpeggiator & Rhythmic Sequencer","skillBand":"Textbook","duration":"From the course textbook","summary":"The internal arpeggiator engine of the Launchkey MK4 61 transforms sustained polyphonic keyboard input into rhythmically clocked, evolving monophonic and polyphonic sequences. This module covers engine activation, latching mechanics, the 8 ","modules":[{"id":"launchkey-m-10-1-1","code":"10.1","title":"The Advanced Arpeggiator & Rhythmic Sequencer","blurb":"The internal arpeggiator engine of the Launchkey MK4 61 transforms sustained polyphonic keyboard input into rhythmically clocked, evolving monophonic and polyphonic sequences. This module covers engine activation, latching mechanics, the 8 ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-29","title":"Section overview","blocks":[{"type":"step","title":"Section 10.1 — Arpeggiator Architecture, Latching & Parameter Interface","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The internal arpeggiator engine of the Launchkey MK4 61 transforms sustained polyphonic keyboard input into rhythmically clocked, evolving monophonic and polyphonic sequences. This module covers engine activation, latching mechanics, the 8 continuous rotary parameters, tempo synchronization (internal vs external clock), and zone source routing."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Engage the arpeggiator engine via the dedicated <code>Arp</code> button and execute latching via <code>Shift + Arp</code>.","Formulate the parameter assignments across all 8 continuous rotary encoders.","Contrast internal tempo generation (40–240 BPM) with host MIDI clock slaving.","Route the arpeggiator input zone using the <code>Arp Note Source</code> setting."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-1-1","title":"10.1.1: Arpeggiator Activation & Latch Mode","blocks":[{"type":"step","title":"10.1.1: Arpeggiator Activation & Latch Mode","blocks":[{"type":"list","items":["<strong>Engine Toggle</strong>: Pressing the dedicated <code>Arp</code> button engages the arpeggiator (button illuminates solid bright blue).","<strong>Arp Latch Mode (<code>Shift + Arp</code>)</strong>:","Holding <code>Shift</code> and pressing <code>Arp</code> activates <strong>Latch</strong> (silkscreened <code>Latch</code>).","When latched, held keys continue arpeggiating indefinitely after physical release.","Playing a new chord or note replaces the sustaining arpeggio pattern.","Pressing <code>Shift + Arp</code> again disables Latch."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-1-2","title":"10.1.2: The 8-Encoder Arpeggiator Parameter Matrix","blocks":[{"type":"step","title":"10.1.2: The 8-Encoder Arpeggiator Parameter Matrix","blocks":[{"type":"prose","html":"When Arp mode is active, Encoders 1–8 automatically map to the arpeggiator engine registers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    ARPEGGIATOR ROTARY PARAMETER MATRIX                        |\n+---------------+-------------------+---------------------+---------------------+\n| Encoder       | Parameter Name    | Factory Default     | Permitted Range     |\n+---------------+-------------------+---------------------+---------------------+\n| **Encoder 1** | **Tempo**         | **120 BPM**         | 40 – 240 BPM        |\n| **Encoder 2** | **Swing**         | **0%**              | -80% to +80%        |\n| **Encoder 3** | **Rate**          | **1/16**            | 1/4, 1/4T ... 1/32T |\n| **Encoder 4** | **Gate**          | **50%**             | 0% – 95% (110% Tie) |\n| **Encoder 5** | **Type**          | **Up**              | 8 Playback Types    |\n| **Encoder 6** | **Octave**        | **1**               | 1 – 4 Octaves       |\n| **Encoder 7** | **Mutate**        | **0**               | 0 – 127 (Intervals) |\n| **Encoder 8** | **Rhythm**        | **1**               | Preset Rest Patterns|\n+---------------+-------------------+---------------------+---------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-10-1-3","title":"10.1.3: Internal Tempo vs. Host MIDI Clock Slaving","blocks":[{"type":"step","title":"10.1.3: Internal Tempo vs. Host MIDI Clock Slaving","blocks":[{"type":"list","items":["<strong>Standalone (Internal Clock)</strong>: When no external MIDI clock is detected, Encoder 1 manually sets tempo from <strong>40 to 240 BPM</strong>.","<strong>DAW Slaved (External Clock)</strong>: When Ableton Live or an external sequencer transmits MIDI Clock (<code>0xF8</code>) via USB, the Launchkey automatically locks to the external tempo.","Turning Encoder 1 in slaved mode displays the received host BPM on the OLED screen."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-1-4","title":"10.1.4: Arp Note Source (Zoned Arpeggiation)","blocks":[{"type":"step","title":"10.1.4: Arp Note Source (Zoned Arpeggiation)","blocks":[{"type":"prose","html":"In Settings -&gt; <code>Arp Note Source</code>:"},{"type":"list","items":["<strong>Part A (Default)</strong>: The arpeggiator listens strictly to keybed Part A (Channel 1).","<strong>Part B</strong>: The arpeggiator listens strictly to keybed Part B (Channel 2).","<em>Studio Utility</em>: In Split Mode (Module 11), setting Arp Note Source to Part A allows an arpeggiated bassline in the left hand while playing a manual synth solo with the right hand in Part B."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Arp activation; Latch (<code>Shift+Arp</code>); full 8-encoder table; Internal 40–240 BPM vs slaved MIDI clock; Arp Note Source (Part A / Part B).","<strong>mustNotCover</strong>: Invention of undocumented 5th octave ranges or sub-menus."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Engage the Arpeggiator, latch a minor triad using <code>Shift + Arp</code>, rotate Encoder 1 to confirm tempo adjustment, and verify all 8 encoder readouts on the OLED screen."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Arpeggio continues sustaining after releasing keys.","All 8 encoder parameters display exact numerical readouts on the OLED display."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-10-2-2","code":"10.2","title":"The Advanced Arpeggiator & Rhythmic Sequencer","blurb":"The Launchkey MK4 61 arpeggiator incorporates diverse rhythmic division rates, swing algorithms, dynamic gate durations, eight distinct playback direction modes (including physical Strum Mode), octave span multipliers, rest rhythm generator","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-30","title":"Section overview","blocks":[{"type":"step","title":"Section 10.2 — Arpeggio Timing, Playback Typology & Mutation","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Launchkey MK4 61 arpeggiator incorporates diverse rhythmic division rates, swing algorithms, dynamic gate durations, eight distinct playback direction modes (including physical Strum Mode), octave span multipliers, rest rhythm generators, and a probabilistic pitch mutation engine. This module provides a complete technical analysis of these timing, playback, and generative functions."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Configure rhythmic divisions (<strong>Rate</strong>) across straight and triplet subdivisions.","Apply groove timing displacement via the <strong>Swing</strong> algorithm (<code>-80%</code> to <code>+80%</code>).","Formulate gate duration scaling from staccato (<code>0%</code>) to legato (<code>95%</code>) and sustained <strong>Tie</strong> (<code>110%</code>).","Detail all 8 playback <strong>Type</strong> modes, including the exact distinction between <strong>Up/Down</strong> and <strong>Up/Down 2</strong>, and the modulation-driven <strong>Strum Mode</strong>.","Formulate the official mathematical semitone mutation table across the 0–127 <strong>Mutate</strong> range.","Contrast the <strong>Rhythm</strong> encoder rest generator with manual pattern editing."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-2-1","title":"10.2.1: Rhythmic Divisions (Rate) & Swing Dynamics","blocks":[{"type":"step","title":"10.2.1: Rhythmic Divisions (Rate) & Swing Dynamics","blocks":[{"type":"list","items":["<strong>Division Rates (Encoder 3)</strong>:","Permitted Values: <code>1/4</code>, <code>1/4T</code> (Triplet), <code>1/8</code>, <code>1/8T</code>, <code>1/16</code> (Default), <code>1/16T</code>, <code>1/32</code>, <code>1/32T</code>.","<strong>Swing Offset (Encoder 2)</strong>:","Range: <strong>-80% to +80%</strong> (Default = <strong>0%</strong>).","<em>Timing Mechanics</em>: Positive swing delays even-numbered steps (offbeats) toward the subsequent downbeat; negative swing advances offbeats ahead of the grid."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-2-2","title":"10.2.2: Gate Duration & The 110% Legato Tie","blocks":[{"type":"step","title":"10.2.2: Gate Duration & The 110% Legato Tie","blocks":[{"type":"list","items":["<strong>Standard Gate Range (Encoder 4)</strong>: <strong>0% to 95%</strong> of the step duration (Default = <strong>50%</strong>).","<strong>Legato Tie (110%)</strong>: When a step is flagged with a <strong>Tie</strong> (via Pattern Mode), the gate length extends to <strong>110%</strong>, overlapping into the subsequent step to trigger synthesizer portamento/legato slides without re-triggering envelopes."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-10-2-3","title":"10.2.3: Authoritative Catalog of 8 Arp Playback Types","blocks":[{"type":"step","title":"10.2.3: Authoritative Catalog of 8 Arp Playback Types","blocks":[{"type":"prose","html":"Encoder 5 selects among 8 discrete playback algorithms:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    THE 8 ARPEGGIATOR PLAYBACK TYPES                           |\n+----+-------------------+------------------------------------------------------+\n| #  | Playback Type     | Directional / Voice Output Behavior                  |\n+----+-------------------+------------------------------------------------------+\n| 1  | **Up**            | Ascends strictly from lowest to highest pitch        |\n| 2  | **Down**          | Descends strictly from highest to lowest pitch       |\n| 3  | **Up/Down**       | Ascends then descends.                               |\n|    |                   | *Highest and lowest turnaround notes ARE NOT REPEATED|\n|    |                   | Example: C -&gt; E -&gt; G -&gt; E -&gt; C -&gt; E -&gt; G ...         |\n+----+-------------------+------------------------------------------------------+\n| 4  | **Up/Down 2**     | Ascends then descends.                               |\n|    |                   | *Highest and lowest turnaround notes ARE REPEATED*   |\n|    |                   | Example: C -&gt; E -&gt; G -&gt; G -&gt; E -&gt; C -&gt; C -&gt; E ...    |\n+----+-------------------+------------------------------------------------------+\n| 5  | **As Played**     | Arpeggiates notes in exact order of physical key-down|\n| 6  | **Random**        | Generates a randomized permutation of held notes     |\n| 7  | **Chord**         | Retriggers ALL held notes simultaneously on every step|\n| 8  | **Strum**         | Notes DO NOT fire automatically with clock.          |\n|    |                   | Notes fire dynamically as the MODULATION WHEEL is    |\n|    |                   | physically moved while keys/chords are held!         |\n+----+-------------------+------------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-10-2-4","title":"10.2.4: Multi-Octave Range Traversal","blocks":[{"type":"step","title":"10.2.4: Multi-Octave Range Traversal","blocks":[{"type":"list","items":["<strong>Octave Parameter (Encoder 6)</strong>: Numerical range <strong>1 to 4</strong> (Default = <strong>1</strong>).","When set to 2, 3, or 4 octaves, the entire arpeggio pattern cycles across the base octave, then repeats at +12, +24, and +36 semitones before cycling back to the root."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-10-2-5","title":"10.2.5: The Probabilistic Mutate Engine","blocks":[{"type":"step","title":"10.2.5: The Probabilistic Mutate Engine","blocks":[{"type":"prose","html":"Encoder 7 injects generative melodic variations by substituting held notes with specific diatonic and chromatic intervals according to an authoritative table:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 AUTHORITATIVE MUTATE INTERVAL TABLE (ENCODER 7)               |\n+---------------------+---------------------------------------------------------+\n| Encoder 7 Range     | Permitted Mutation Pitch Intervals (Semitones)          |\n+---------------------+---------------------------------------------------------+\n| **0**               | **None** (Pure original notes)                          |\n| **1 – 19**          | **+12 st** (Octave Up)                                  |\n| **20 – 63**         | **+12 st, -12 st, -7 st** (Octaves and 5ths)            |\n| **64 – 100**        | **+12 st, -12 st, -7 st, +7 st**                        |\n| **101 – 115**       | Above intervals plus **+3 st, +4 st, +10 st**           |\n| **116 – 127**       | Full Chromatic Chaos: **Any interval from -12 to +12 st**|\n+---------------------+---------------------------------------------------------+</pre>"},{"type":"prose","html":"<em>Mutation Cycle Mechanics</em>: A new mutation permutation is generated whenever Encoder 7 is moved or when keys are released and restruck; the generated pattern then repeats deterministically."}]}],"minutes":8},{"id":"launchkey-l-10-2-6","title":"10.2.6: Rhythm Rest Patterns & Overwrite Warning","blocks":[{"type":"step","title":"10.2.6: Rhythm Rest Patterns & Overwrite Warning","blocks":[{"type":"list","items":["<strong>Rhythm (Encoder 8)</strong>: Cycles through pre-programmed rest/pause patterns across the arpeggio grid.","<em>CRITICAL DESTRUCTIVE WARNING</em>: Turning Encoder 8 <strong>instantly overwrites and clears any custom step edits</strong> previously programmed in Arp Pattern Mode."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Rate divisions; Swing (-80% to +80%); Gate (0–95% / 110% Tie); all 8 Types (including Up/Down vs Up/Down 2 distinction and Mod-Wheel Strum mode); Octaves 1–4; authoritative Mutate interval table; Rhythm encoder overwrite warning.","<strong>mustNotCover</strong>: Speculation regarding undocumented 9th arp types."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Latch a 3-note chord. Test Type <strong>Up/Down</strong> and compare audibly with <strong>Up/Down 2</strong> to observe turnaround note repetition. Select <strong>Strum Mode</strong>, hold keys, and sweep the Modulation Wheel to trigger strummed chords. Turn <strong>Mutate</strong> to 80 and observe interval variations."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Audibly verified: Up/Down does not repeat apex notes; Up/Down 2 doubles apex notes.","Strum mode triggers notes only upon Mod Wheel movement.","Mutate table adheres to the official semitone ranges."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-10-3-3","code":"10.3","title":"The Advanced Arpeggiator & Rhythmic Sequencer","blurb":"Arp Pattern Mode transforms the 16-pad RGB matrix into a visual, tactile 16-step rhythm editor for the internal arpeggiator engine. Performers can toggle active steps and rests on the top row while applying step-specific modifiers—Accent, R","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-31","title":"Section overview","blocks":[{"type":"step","title":"Section 10.3 — 16-Step Arp Pattern Matrix","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Arp Pattern Mode transforms the 16-pad RGB matrix into a visual, tactile 16-step rhythm editor for the internal arpeggiator engine. Performers can toggle active steps and rests on the top row while applying step-specific modifiers—<strong>Accent</strong>, <strong>Ratchet</strong>, and <strong>Tie</strong>—on the bottom row using the multi-state <code>Function</code> button."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Initialize Arp Pattern pad mode via the <code>Shift + Pad 12</code> command.","Toggle active rhythm steps and rests across the step matrix with real-time white playhead tracking.","Cycle the <code>Function</code> button across the three modifier modes: <strong>Accent</strong> (Orange), <strong>Ratchet</strong> (Yellow), and <strong>Tie</strong> (Red).","Formulate the mathematical execution of <strong>Tie</strong> (110% Gate), <strong>Accent</strong> (+30 Velocity), and <strong>Ratchet</strong> (Double-trigger subdivision).","Prevent destructive pattern clearing caused by the Rhythm encoder.","Complete Assessment Gate H."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-3-1","title":"10.3.1: Arp Pattern Mode Initialization","blocks":[{"type":"step","title":"10.3.1: Arp Pattern Mode Initialization","blocks":[{"type":"list","items":["<strong>Activation</strong>: Hold <code>Shift</code> and press <strong>Pad 12</strong> (silkscreened <code>Arp Pattern</code>).","<strong>OLED Readout</strong>: Displays <code>Pad Mode: Arp Pattern</code>.","<strong>Top/Bottom Row Division</strong>:","<strong>Top Row (Pads 1–8)</strong>: Step on/off triggers and real-time visual playhead.","<strong>Bottom Row (Pads 9–16)</strong>: Contextual step modifier triggers."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-10-3-2","title":"10.3.2: Top Row Step Activation & Visual Playhead","blocks":[{"type":"step","title":"10.3.2: Top Row Step Activation & Visual Playhead","blocks":[{"type":"list","items":["<strong>Step States</strong>:","<strong>Solid Blue</strong>: Active step (note triggers on this clock pulse).","<strong>Unlit / Extinguished</strong>: Rest (arpeggiator pauses on this clock pulse).","<strong>Moving White Playhead</strong>: As the arpeggiator clocks, an illuminated <strong>solid white LED</strong> traverses the pads in real time, showing the exact active playback position."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-10-3-3","title":"10.3.3: Bottom Row Step Modifiers & Function Cycling","blocks":[{"type":"step","title":"10.3.3: Bottom Row Step Modifiers & Function Cycling","blocks":[{"type":"prose","html":"Pressing the physical <code>Function</code> button steps through three modifier modes, altering the LED color of the <code>Function</code> button and the bottom pad row:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    ARP PATTERN STEP MODIFIER MODES                            |\n+-------------+---------------+-----------------------+-------------------------+\n| Modifier    | LED Color     | Function &amp; Pad Color  | Technical Execution     |\n+-------------+---------------+-----------------------+-------------------------+\n| **ACCENT**  | **ORANGE**    | Solid Bright Orange   | Adds **+30 Velocity**   |\n|             |               |                       | (Maximum ceiling: 127)  |\n+-------------+---------------+-----------------------+-------------------------+\n| **RATCHET** | **YELLOW**    | Solid Bright Yellow   | Splits step into **TWO  |\n|             |               |                       | triggers** (1/32 notes) |\n+-------------+---------------+-----------------------+-------------------------+\n| **TIE**     | **RED**       | Solid Bright Red      | Extends Gate to **110%**|\n|             |               |                       | for seamless legato     |\n+-------------+---------------+-----------------------+-------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       MODIFIER PROGRAMMING WORKFLOW:\n1. Press [ Function ] until LED turns ORANGE (Accent Mode).\n2. Tap Pad 9 (Step 1) -&gt; Pad 9 turns Orange (Step 1 is now Accented).\n3. Press [ Function ] -&gt; LED turns YELLOW (Ratchet Mode).\n4. Tap Pad 11 (Step 3) -&gt; Pad 11 turns Yellow (Step 3 now Ratchets).\n5. Press [ Function ] -&gt; LED turns RED (Tie Mode).\n6. Tap Pad 12 (Step 4) -&gt; Pad 12 turns Red (Step 4 now Ties into Step 5).</pre>"},{"type":"prose","html":"<em>Dual Modifier Rule</em>: If both Ratchet and Accent are active on the same step, the +30 velocity boost is applied to both ratcheted notes."}]}],"minutes":8},{"id":"launchkey-l-10-3-4","title":"10.3.4: Destructive Rhythm Overwrite Warning","blocks":[{"type":"step","title":"10.3.4: Destructive Rhythm Overwrite Warning","blocks":[{"type":"list","items":["If custom steps, Ties, Accents, or Ratchets have been programmed into the pad matrix, <strong>do not rotate Encoder 8 (Rhythm)</strong>.","Moving Encoder 8 instantly wipes the custom pad matrix and replaces it with the selected factory rest template."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Arp Pattern mode entry (<code>Shift + Pad 12</code>); top row step/rest toggle + white playhead; Function cycle across Accent (Orange, +30 vel), Ratchet (Yellow, double trigger), and Tie (Red, 110% gate); Rhythm encoder overwrite warning.","<strong>mustNotCover</strong>: Confusing Arp Pattern Mode with the Ableton Live Clip Step Sequencer (covered in Module 14)."],"ordered":false}]},{"type":"step","title":"Assessment Gate H (Advanced Arpeggiator Validation)","blocks":[{"type":"prose","html":"<strong>Objective</strong>: Demonstrate complete operational mastery of the Arpeggiator engine, timing parameters, and the 16-Step Pattern matrix."},{"type":"prose","html":"<strong>Self-Assessment Checklist</strong>:"},{"type":"list","items":["[ ] Engage Arp, latch a minor 7th chord with <code>Shift + Arp</code>, and adjust Rate (<code>1/16</code>), Gate (<code>65%</code>), and Swing (<code>+25%</code>).","[ ] Test Playback Types: Up, Down, Up/Down, Up/Down 2, and verify Strum Mode triggers notes via the Modulation Wheel.","[ ] Enter Arp Pattern Mode (<code>Shift + Pad 12</code>). Program a custom 8-step rhythm with 2 rests.","[ ] Using the <code>Function</code> button, program one <strong>Accented</strong> step (Orange), one <strong>Ratcheted</strong> step (Yellow), and one <strong>Tied</strong> step (Red).","[ ] Confirm the audible results in the audio output stream."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
